(() => {
  const image = document.querySelector('[data-dsh-test-viewer] img')
  const rect = image.getBoundingClientRect()
  const x = rect.left + rect.width / 2
  const y = rect.top + rect.height / 2
  const read = () => (image.getAttribute('data-dsh-image-zoom') === null ? null : Number(image.getAttribute('data-dsh-image-zoom')))
  image.dispatchEvent(new MouseEvent('dblclick', { clientX: x, clientY: y, bubbles: true, cancelable: true }))
  const scales = [read()]
  for (const delta of [-120, -120, 120, 120]) {
    image.dispatchEvent(new WheelEvent('wheel', { deltaY: delta, clientX: x, clientY: y, bubbles: true, cancelable: true }))
    scales.push(read())
  }
  window.__zoomScales = JSON.stringify(scales)
  return window.__zoomScales
})()

(() => {
  const image = document.querySelector('[data-dsh-test-viewer] img')
  const rect = image.getBoundingClientRect()
  const x = rect.left + rect.width * 0.3
  const y = rect.top + rect.height * 0.4
  image.dispatchEvent(new MouseEvent('dblclick', { clientX: x, clientY: y, bubbles: true, cancelable: true }))
  const before = image.getBoundingClientRect()
  image.dispatchEvent(new WheelEvent('wheel', { deltaY: -120, clientX: x, clientY: y, bubbles: true, cancelable: true }))
  const after = image.getBoundingClientRect()
  const scale = Number(image.getAttribute('data-dsh-image-zoom'))
  window.__zoomAnchor = JSON.stringify({ delta: Math.abs(after.left + (x - before.left) * scale - x), scale })
  return window.__zoomAnchor
})()

